export type RetryOptions = {
  /** Maximum number of attempts (including the first try). */
  maxAttempts?: number;

  /** Initial delay in ms before the first retry. */
  baseDelay?: number;

  /** Maximum delay in ms for the back‑off ceiling. */
  maxDelay?: number;

  /** Whether to add a random jitter (0‑1) to each delay to avoid thundering herd. */
  jitter?: boolean;

  /** Which errors are considered retryable. If undefined, all errors are retried. */
  retryableErrors?: Set<Error> | (() => Error | boolean);

  /** Optional callback for each attempt (useful for logging). */
  onRetry?: (attempt: number, error: Error) => void;
};

